        singleVariant("release") {
            withSourcesJar()
        }
    }
}

publishing {
    publications {
        create<MavenPublication>("release") {
            groupId = "com.example"
            artifactId = "analytics"
            version = "1.4.0"
            from(components["release"])
        }
    }
    repositories {
