}

// lint-rules module — compiled as a separate Gradle module
class AndroidConventionRules : IssueRegistry() {
    override val issues: List<Issue> = listOf(
        Issue.create(
            id = "NoLogInRelease",
            briefDescription = "Log statements in release code",
            explanation = "android.util.Log calls leak data and add noise.",
            category = Category.CORRECTNESS,
            priority = 9,
            severity = Severity.ERROR,
            implementation = Implementation(
                NoLogDetector::class.java,
                Scope.JAVA_FILE
            )
        )
    )
}

// app module wiring
android {
    lint {
        baseline = file("lint-baseline.xml")
        abortOnError = true
        checkReleaseBuilds = false
    }
}

dependencies {
    lintChecks(project(":lint-rules"))
}
